using System;using System.Threading.Tasks;using CTXD.Client.Features.FirstPlayable;using CTXD.Client.Networking;using UnityEngine;using UnityEngine.UI;
namespace CTXD.Client.Features.Market { public sealed class MarketPanel:MonoBehaviour { ApiClient _api;Action<string> _status;RectTransform _window;MarketView _view;public static MarketPanel Open(RectTransform host,ApiClient api,Action<string> status){var go=new GameObject("MarketPanel");go.transform.SetParent(host,false);var p=go.AddComponent<MarketPanel>();p._api=api;p._status=status;p.Build();_=p.Refresh();return p;}void Build(){var blocker=LegacyUiFactory.Panel(transform,"MarketBlocker",Vector2.zero,Vector2.one,new Color(0,0,0,.88f));_window=LegacyUiFactory.PixelPanel(blocker,"MarketWindow",285,120,710,450,new Color(.055f,.035f,.018f,1));}async Task Refresh(){try{_view=await _api.GetMarketAsync();Draw();}catch(Exception ex){_status(ex.Message);Destroy(gameObject);}}void Draw(){LegacyUiFactory.DestroyChildren(_window);LegacyUiFactory.PixelLabel(_window,"MARKET",24,TextAnchor.MiddleCenter,new Color(1,.8f,.3f),190,15,330,34);LegacyUiFactory.PixelButton(_window,"Close",610,18,70,28,()=>Destroy(gameObject));LegacyUiFactory.PixelLabel(_window,"Purchases: "+_view.canBuy+"/24",15,TextAnchor.MiddleLeft,Color.white,30,60,250,25);var offers=_view.offers??Array.Empty<MarketOfferView>();for(var i=0;i<offers.Length;i++){var o=offers[i];var y=105+i*80;LegacyUiFactory.PixelLabel(_window,o.itemType+" x"+o.itemNum+"  Q"+o.quality,17,TextAnchor.MiddleLeft,Color.white,40,y,310,28);LegacyUiFactory.PixelLabel(_window,o.costType+" "+o.costNum,15,TextAnchor.MiddleLeft,new Color(1,.75f,.35f),40,y+29,260,25);LegacyUiFactory.PixelButton(_window,"Buy",490,y+8,120,32,async()=>{try{var r=await _api.BuyMarketAsync(o.slot,Guid.NewGuid().ToString("N"));_status("Market: +"+r.added+" "+r.itemType);await Refresh();}catch(Exception ex){_status(ex.Message);}});}LegacyUiFactory.PixelButton(_window,"Black market",500,380,150,30,async()=>{try{var b=await _api.GetBlackMarketAsync();_status("Black market: spend "+b.spend+", receive "+b.receive);}catch(Exception ex){_status(ex.Message);}});}} }
